/* SaaS account, workspace and administration UI. Credentials never enter browser storage. */
(() => {
  'use strict';
  const $ = s => document.querySelector(s);
  const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const publicRoutes = ['home', 'login', 'signup', 'forgot', 'reset', 'verify', 'accept-invite', 'terms', 'privacy'];
  const adminRoutes = ['branding', 'team', 'billing', 'audit', 'security', 'integrations'];
  const S = window.SaaS = { enabled: location.protocol !== 'file:', account: null, state: null, version: 0, cache: {}, offline: false, saving: false, pending: Promise.resolve(), generation: 0, logo: null, publicBrand: null, notice: '', route: '' };
  S.api = async (path, method = 'GET', body) => {
    const response = await fetch(`/api${path}`, { method, credentials: 'same-origin', headers: { ...(S.account ? { 'X-Workspace-Id': S.account.tenant.id } : {}), ...(method !== 'GET' ? { 'Content-Type': 'application/json', 'X-CSRF-Token': S.account?.csrf || '' } : {}) }, ...(body !== undefined ? { body: JSON.stringify(body) } : {}) });
    const result = await response.json().catch(() => ({ error: 'Start the SaaS server with npm start to use accounts and workspaces.' }));
    if (!response.ok) { const error = new Error(result.error || 'Request failed.'); error.status = response.status; error.details=result; if (response.status === 401 && S.account) { S.account = null; S.state = null; S.cache = {}; S.refresh(); } throw error; }
    return result;
  };
  S.refresh = () => window.dispatchEvent(new Event('saas-render'));
  S.notify = message => { const toast = $('#toast'); if (toast) { toast.textContent = message; toast.classList.add('show'); clearTimeout(S.toastTimer); S.toastTimer = setTimeout(() => toast.classList.remove('show'), 5500); } };
  S.syncBrand = () => {
    const brand = document.body.dataset.view === 'subscriber' ? S.publicBrand : S.account?.tenant;
    const color = brand?.color || '#087f5b';
    document.documentElement.style.setProperty('--green', color);
    const dark='#'+[1,3,5].map(i=>Math.round(parseInt(color.slice(i,i+2),16)*.78).toString(16).padStart(2,'0')).join('');
    document.documentElement.style.setProperty('--green-dark', dark);
    document.documentElement.style.setProperty('--green-soft', `${color}12`);
    let favicon = $('link[rel="icon"]');
    if (!favicon) { favicon = document.createElement('link'); favicon.rel = 'icon'; document.head.append(favicon); }
    if (brand?.logo) favicon.href = brand.logo;
    else { const letter = (brand?.name || 'T').slice(0, 1).replace(/[^a-z0-9]/gi, 'T'); favicon.href = `data:image/svg+xml,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="16" fill="${color}"/><text x="32" y="45" fill="white" font-family="sans-serif" font-size="42" text-anchor="middle">${letter.toUpperCase()}</text></svg>`)}`; }
    $('meta[name="theme-color"]')?.setAttribute('content', color);
  };
  S.brand = (brand = S.account?.tenant || S.publicBrand) => {
    const name = brand?.name || 'Techzolo';
    const initials = name.trim().split(/\s+/).slice(0, 2).map(v => v[0] || '').join('').toUpperCase();
    return `<div class="brand">${brand?.logo ? `<img class="company-logo" src="${esc(brand.logo)}" alt="${esc(name)} logo">` : `<span class="brand-mark">${esc(initials)}</span>`}<div class="brand-copy"><div class="brand-name">${esc(name)}<span class="brand-period">.</span></div><div class="brand-subtitle">${brand ? 'Your customer workspace' : 'Conversations. Connected.'}</div></div></div>`;
  };
  S.loadWorkspace = async () => {
    const result = await S.api('/workspace'); S.state = result.state; S.version = result.version; S.cache = {}; S.syncBrand();
    window.dispatchEvent(new Event('saas-state'));
  };
  S.save = state => {
    const snapshot = JSON.parse(JSON.stringify(state)), generation = S.generation;
    S.pendingCount=(S.pendingCount||0)+1; S.saving = true; S.updateSaveStatus('Saving…');
    S.pending = S.pending.then(async () => {
      if (generation !== S.generation) return;
      try {
        const result = await S.api('/workspace', 'PUT', { state: snapshot, version: S.version });
        S.version = result.version; S.state = snapshot; S.cache = {};
        if (S.account) { S.account.tenant.name = snapshot.settings.business; S.syncBrand(); }
        S.notice = ''; S.updateSaveStatus('All changes saved');
      } catch (error) {
        S.generation++; S.notice = error.message;
        if (S.account) {
          try { S.account=await S.api('/session'); await S.loadWorkspace(); }
          catch(recovery) { if(![401,403].includes(recovery.status)) S.offline=true; }
        }
        S.refresh(); S.notify(error.message);
      }
    }).finally(() => { S.pendingCount--; S.saving = S.pendingCount>0; });
    return S.pending;
  };
  S.updateSaveStatus = message => { const status = $('#save-status'); if (status) status.textContent = message; };
  S.ready = (async () => {
    if (!S.enabled) return;
    if (document.body.dataset.view === 'subscriber') {
      const slug = new URLSearchParams(location.search).get('workspace');
      if (!slug) { S.notice = 'This signup link is missing its company workspace. Ask the business for its signup link.'; return; }
      try { S.publicBrand = await S.api(`/public/${encodeURIComponent(slug)}`); S.syncBrand(); } catch (e) { S.notice = e.message; }
      return;
    }
    try { S.account = await S.api('/session'); await S.loadWorkspace(); }
    catch (error) { if (error.status !== 401) S.offline = true; }
    const slug = new URLSearchParams(location.hash.split('?')[1]).get('workspace');
    if (!S.account && slug) { try { S.publicBrand = await S.api(`/public/${encodeURIComponent(slug)}`); S.syncBrand(); } catch {} }
  })();
  const input = (label, name, type = 'text', extra = '', value = '') => `<div class="field"><label for="saas-${name}">${label}</label><input id="saas-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;
  const submit = text => `<button class="btn primary" type="submit">${text}<span aria-hidden="true">↗</span></button>`;
  const header = (title, text, actions = '') => `<div class="page-heading"><div><p class="eyebrow">YOUR WORKSPACE, YOUR WAY</p><h1>${title}</h1><p>${text}</p></div><div class="row gap-sm">${actions}</div></div>`;
  const alert = (text, type = '') => `<div class="saas-alert ${type}" role="status">${text}</div>`;
  const icon = text => `<span class="feature-symbol" aria-hidden="true">${text}</span>`;
  function landing() {
    return `<div class="marketing"><header class="marketing-nav"><a href="#home" aria-label="Techzolo home">${S.brand(null)}</a><nav aria-label="Website navigation"><a href="#home" data-scroll="features">Features</a><a href="#home" data-scroll="pricing">Pricing</a><a href="#login">Sign in</a><a href="#signup" class="btn primary">Start free trial <span>↗</span></a></nav></header><main id="main"><section class="marketing-hero"><div class="hero-copy"><span class="hero-pill"><span class="dot"></span>A home for every customer conversation</span><h1>Small moments.<br><em>Stronger</em><br>relationships.</h1><p>Bring your customers, conversations and team together in a workspace that feels like your business.</p><div class="row wrap"><a class="btn primary hero-cta" href="#signup">Create your workspace <span>↗</span></a><a class="text-link" href="#home" data-scroll="features">Take a closer look ↓</a></div><div class="hero-details"><span>✓ 14-day Growth trial</span><span>✓ No credit card required</span><span>✓ Your own branding</span></div></div><div class="hero-preview" aria-label="Illustration of a branded CRM workspace"><div class="preview-chrome"><span></span><span></span><span></span><p>YOUR COMPANY · YOUR WORKSPACE</p></div><div class="preview-body"><aside><span class="preview-monogram">Y</span><i class="active">◫ Overview</i><i>◉ Inbox</i><i>♧ Contacts</i><i>↗ Campaigns</i><i>⚙ Settings</i><div class="preview-team">Your team.<br>All together.</div></aside><div class="preview-content"><div class="row between"><span class="eyebrow">GOOD CONVERSATIONS START HERE</span><span class="preview-avatar">JD</span></div><h2>A little closer to<br>your customers.</h2><div class="preview-stats"><div><span>Conversations</span><strong>1,284</strong><small>↗ 12.8% this week</small></div><div><span>Happy customers</span><strong>96.8<span>%</span></strong><small>Every connection counts</small></div></div><div class="preview-chart"><span>Conversation activity</span><svg viewBox="0 0 420 110" aria-hidden="true"><path d="M0 99 Q25 90 45 95 T90 70 T135 80 T180 48 T225 55 T270 25 T315 35 T360 12 T420 4 L420 110H0Z" fill="#e4f1e9"/><path d="M0 99 Q25 90 45 95 T90 70 T135 80 T180 48 T225 55 T270 25 T315 35 T360 12 T420 4" fill="none" stroke="#16835f" stroke-width="3"/></svg><small>MON<span>WED</span><span>FRI</span><span>SUN</span></small></div><div class="preview-message"><span class="preview-avatar peach">AK</span><div><strong>Aarav Kapoor</strong><p>Thanks for the quick reply! ✨</p></div><small>Just now</small></div></div></div><span class="preview-label">Illustrative product preview</span></div></section><div class="marketing-strip"><span>ONE WORKSPACE. A LOT MORE POSSIBILITY.</span><strong>Conversations</strong><b>✳</b><strong>Customers</strong><b>✳</b><strong>Campaigns</strong><b>✳</b><strong>Your team</strong></div><section id="features" class="marketing-section"><p class="eyebrow">BUILT FOR YOUR NEXT CHAPTER</p><h2>Everything in its place.<br>Everyone on the same page.</h2><div class="feature-grid">${[['◉', 'A shared customer inbox', 'Keep conversation drafts, customer context and internal notes together.'], ['♧', 'Customer relationships', 'Organize contacts, import a CSV and follow opportunities through your pipeline.'], ['✳', 'A workspace that is yours', 'Add your company logo and color. Your brand follows your team and signup page.'], ['◈', 'Room for the whole team', 'Invite owners, admins, agents and viewers with clearly defined permissions.'], ['↗', 'Plans that grow with you', 'See your usage, understand your limits and manage subscriptions with Stripe.'], ['✓', 'Control you can see', 'Separate company data, secure sessions and a clear record of workspace changes.']].map(([i,t,d])=>`<article>${icon(i)}<h3>${t}</h3><p>${d}</p></article>`).join('')}</div>${alert('CRM workflows are available now. WhatsApp delivery and AI require provider integrations; creating an account does not connect or send messages.')}</section><section id="pricing" class="marketing-section pricing-section"><p class="eyebrow">A CLEAR PLAN FOR WHAT COMES NEXT</p><h2>Start small. Make room to grow.</h2><p>Every workspace starts with 14 days of Growth. Prices below are the configured product catalog, per workspace per month. WhatsApp provider fees and taxes are additional.</p><div class="pricing-grid">${planCards(false)}</div></section><section class="marketing-end"><p class="eyebrow">YOUR NEXT CONVERSATION STARTS HERE</p><h2>Make it your workspace.</h2><a href="#signup" class="btn primary hero-cta">Start your free trial ↗</a></section></main><footer class="marketing-footer"><span>Techzolo · Customer connections, thoughtfully organized.</span><div><a href="#terms">Terms</a><a href="#privacy">Privacy</a><a href="#login">Sign in</a></div></footer></div>`;
  }
  function planCards(inApp) {
    const plans = S.account?.plans || { starter: { name: 'Starter', price: 1499, contacts: 1000, seats: 3, campaigns: 10, automations: 3 }, growth: { name: 'Growth', price: 3999, contacts: 5000, seats: 10, campaigns: 100, automations: 25 }, scale: { name: 'Scale', price: 9999, contacts: 10000, seats: 50, campaigns: 1000, automations: 100 } };
    return Object.entries(plans).map(([id,p]) => `<article class="pricing-card ${id === 'growth' ? 'recommended' : ''}">${id === 'growth' ? '<span class="pricing-tag">A LITTLE MORE ROOM TO GROW</span>' : ''}<p class="eyebrow">${esc(p.name)}</p><div class="plan-price">₹${p.price.toLocaleString('en-IN')}<span>/ month</span></div><p>${{ starter: 'For a team finding its rhythm.', growth: 'For growing teams and bigger possibilities.', scale: 'For businesses ready for the next chapter.' }[id]}</p><ul><li>${p.contacts.toLocaleString('en-IN')} contacts</li><li>${p.seats} team seats</li><li>${p.campaigns} saved campaigns</li><li>${p.automations} automation configurations</li><li>Company logo & brand color</li><li>Role permissions & audit history</li></ul>${inApp ? `<button class="btn ${id === 'growth' ? 'primary' : ''}" data-saas="checkout" data-plan="${id}" ${S.account.tenant.role !== 'owner' ? 'disabled' : ''}>${S.account.tenant.plan === id ? 'Subscribe to ' : 'Choose '}${esc(p.name)} ↗</button>` : `<a href="#signup" class="btn ${id === 'growth' ? 'primary' : ''}">Start your free trial ↗</a>`}</article>`).join('');
  }
  function companyFields() {
    return `${input('Company name', 'company', 'text', 'required maxlength="100" autocomplete="organization"')}${input('Workspace URL', 'slug', 'text', 'required minlength="3" maxlength="48" pattern="[a-z0-9]+(-[a-z0-9]+)*" placeholder="your-company" aria-describedby="slug-help"')}<p class="tiny muted" id="slug-help">Lowercase letters, numbers and hyphens. This identifies your company’s public signup page.</p><div class="company-upload"><div class="logo-preview" id="logo-preview">Your<br>logo</div><div class="field grow"><label for="company-logo">Company logo <span class="muted">(optional)</span></label><input type="file" id="company-logo" accept="image/png,image/jpeg,image/webp"><p class="help">PNG, JPEG or WebP · up to 2 MB. You can add it later.</p></div><div class="field"><label for="saas-color">Brand color</label><input type="color" id="saas-color" name="color" value="#087f5b"></div></div>`;
  }
  function auth(route) {
    const signup = route === 'signup', forgot = route === 'forgot', reset = route === 'reset', verify = route === 'verify', invite = route === 'accept-invite';
    let content;
    if (signup) content = `<h1>A fresh start for<br>your business.</h1><p>Create your company workspace. Make it yours from day one.</p><form data-saas-form="register" class="saas-form">${companyFields()}<div class="form-grid">${input('Your name', 'name', 'text', 'required maxlength="100" autocomplete="name"')}${input('Work email', 'email', 'email', 'required autocomplete="email"')}</div>${input('Password', 'password', 'password', 'required minlength="15" maxlength="128" autocomplete="new-password" aria-describedby="password-help"')}<p class="tiny muted" id="password-help">Use 15–128 characters. A memorable passphrase works well.</p><label class="check-label"><input name="terms" type="checkbox" required><span>I agree to the <a class="text-link" href="#terms" target="_blank" rel="noopener">terms</a> and <a class="text-link" href="#privacy" target="_blank" rel="noopener">privacy notice</a>.</span></label><p class="form-error" role="alert"></p>${submit('Create workspace')}</form><p class="auth-switch">Already have an account? <a href="#login">Sign in</a></p>`;
    else if (forgot) content = `<h1>Let’s get you back in.</h1><p>We’ll email you a link to reset your password.</p><form data-saas-form="forgot" class="saas-form">${input('Email address', 'email', 'email', 'required autocomplete="email"')}<p class="form-error" role="alert"></p>${submit('Send recovery email')}</form><p class="auth-switch"><a href="#login">Back to sign in</a></p>`;
    else if (reset) content = `<h1>A new password.<br>A fresh start.</h1><p>Your reset link expires after one hour.</p><form data-saas-form="reset" class="saas-form">${input('New password', 'password', 'password', 'required minlength="15" maxlength="128" autocomplete="new-password"')}<p class="form-error" role="alert"></p>${submit('Reset password')}</form>`;
    else if (verify) content = `<h1>Confirm your email.</h1><p>Finish verifying your account with the link sent to your inbox.</p><form data-saas-form="verify" class="saas-form"><p class="form-error" role="alert"></p>${submit('Verify my email')}</form><p class="auth-switch"><a href="#dashboard">Continue to workspace</a></p>`;
    else if (invite) content = `<h1>You’re invited.</h1><p>Join your team’s workspace using the email address that received this invitation.</p>${S.account ? `<form data-saas-form="accept" class="saas-form"><p class="tiny muted">Signed in as ${esc(S.account.user.email)}</p><p class="form-error" role="alert"></p>${submit('Join workspace')}</form>` : `<div class="stack mt"><a class="btn primary" href="#login">Sign in to accept</a><a class="btn" href="#signup">Create an account</a></div>`}`;
    else content = `<h1>Good to have<br>you back.</h1><p>Your customers, conversations and team are waiting.</p><form data-saas-form="login" class="saas-form">${input('Email address', 'email', 'email', 'required autocomplete="email"')}${input('Password', 'password', 'password', 'required maxlength="128" autocomplete="current-password"')}<a class="text-link auth-forgot" href="#forgot">Forgot your password?</a><p class="form-error" role="alert"></p>${submit('Sign in to your workspace')}</form><p class="auth-switch">New here? <a href="#signup">Create a workspace</a></p>`;
    return `<div class="auth-layout saas-auth"><aside class="auth-story"><a href="#home">${S.brand(S.publicBrand)}</a><div class="auth-story-main"><span class="hero-pill">A LITTLE CLOSER, EVERY DAY</span><h1>Your business.<br>Your brand.<br><em>Your people.</em></h1><p>One thoughtful space for the conversations that move your business forward.</p><div class="auth-brand-art"><span>Y</span><div><strong>Your company, front and center.</strong><p>Your logo and colors belong here.</p></div><b>✳</b></div></div><footer>Techzolo · Made for meaningful connections.</footer></aside><main id="main" class="auth-form"><div class="auth-form-inner"><a href="#home" class="back-home">← Back to Techzolo</a><p class="eyebrow">YOUR NEXT CHAPTER</p>${content}</div></main></div>`;
  }
  function fetchView(key, endpoint, content) {
    if (S.cache[key]?.error) return alert(`${esc(S.cache[key].error)} <button class="text-link" data-saas="retry" data-key="${key}">Try again</button>`);
    if (!S.cache[key]) {
      const entry=S.cache[key] = { loading: true };
      S.api(endpoint).then(data => { if(S.cache[key]!==entry)return;S.cache[key] = { data }; S.refresh(); }).catch(e => { if(S.cache[key]!==entry)return;S.cache[key] = { error: e.message }; S.refresh(); });
      return '<div class="card card-body loading-state" role="status">Loading workspace details…</div>';
    }
    if (S.cache[key].loading) return '<div class="card card-body loading-state" role="status">Loading workspace details…</div>';
    return content(S.cache[key].data);
  }
  function branding() {
    const t = S.account.tenant, canEdit = ['owner', 'admin'].includes(t.role);
    return `${header('Let your brand lead.', 'Your identity, in every corner of your customer workspace.')}<div class="branding-layout"><section class="card"><form data-saas-form="branding" class="card-body saas-form"><div class="section-kicker">WORKSPACE IDENTITY</div><h2>A familiar face for your team.</h2><p class="muted text-sm">Your logo appears in navigation, the browser tab and your public subscriber page.</p><fieldset ${!canEdit ? 'disabled' : ''}><div class="company-upload large"><div class="logo-preview" id="logo-preview">${t.logo ? `<img src="${esc(t.logo)}" alt="Current company logo">` : esc(t.name.slice(0,2).toUpperCase())}</div><div class="field grow"><label for="company-logo">Company logo</label><input id="company-logo" type="file" accept="image/png,image/jpeg,image/webp"><p class="help">PNG, JPEG or WebP · up to 2 MB · up to 16 megapixels.<br>Images are safely resized to a maximum of 512 × 512.</p></div></div><div class="field"><label for="saas-color">Your signature color</label><div class="row"><input name="color" id="saas-color" type="color" value="${esc(t.color)}"><span class="mono tiny muted">Choose a color that feels like you.</span></div></div><label class="check-label"><input name="removeLogo" type="checkbox">Remove the current logo and use company initials</label><p class="form-error" role="alert"></p><div class="form-footer">${submit('Save brand identity')}</div></fieldset></form></section><aside><div class="card brand-preview-card"><span class="section-kicker">YOUR BRAND, IN CONTEXT</span><div id="brand-live-preview">${S.brand(t)}<hr><div class="preview-welcome">Welcome to<br><strong>${esc(t.name)}.</strong></div><p class="tiny muted">A consistent experience for your team and customers.</p><a class="btn primary" href="${S.signupUrl()}" target="_blank" rel="noopener">Preview subscriber page ↗</a></div></div><p class="tiny muted mt">Workspace URL <strong>${esc(t.slug)}</strong><br>Each company has separate branding and data.</p></aside></div>${!canEdit ? alert('Only owners and administrators can update company branding.') : ''}`;
  }
  function team() {
    const role = S.account.tenant.role, canInvite = ['owner', 'admin'].includes(role);
    return `${header('Good work is a team effort.', 'Invite your people. Give everyone the right amount of access.', '<button class="btn" data-saas="retry" data-key="team">Refresh team</button>'+(canInvite ? '<button class="btn primary" data-saas="invite">Invite teammate ↗</button>' : ''))}${fetchView('team','/team', data => `<section class="card"><div class="card-head mb"><div><h2>Your people</h2><p>Pending invitations reserve a seat on your plan.</p></div><span class="badge green">${data.members.length} members</span></div><div class="table-wrap"><table><thead><tr><th>Team member</th><th>Email address</th><th>Role</th><th>Actions</th></tr></thead><tbody>${data.members.map(m=>`<tr><td><strong>${esc(m.name)}</strong>${m.id===S.account.user.id?' <span class="tiny muted">(you)</span>':''}</td><td>${esc(m.email)}</td><td>${role==='owner'&&m.role!=='owner'?`<select aria-label="Role for ${esc(m.name)}" data-member="${esc(m.id)}">${['admin','agent','viewer'].map(r=>`<option ${m.role===r?'selected':''}>${r}</option>`).join('')}</select>`:`<span class="badge ${m.role==='owner'?'green':'gray'}">${esc(m.role)}</span>`}</td><td>${role==='owner'&&m.role!=='owner'?`<button class="text-link danger-text" data-saas="remove-member" data-id="${esc(m.id)}" data-name="${esc(m.name)}">Remove</button>`:'<span class="tiny muted">—</span>'}</td></tr>`).join('')}</tbody></table></div></section>${canInvite?`<section class="card mt"><div class="card-head mb"><h2>Pending invitations</h2></div><div class="card-body">${data.invites.length?data.invites.map(i=>`<div class="setting-row"><div><strong>${esc(i.email)}</strong><p>${esc(i.role)} · Expires ${new Date(i.expires).toLocaleDateString('en-IN')}</p></div><button class="text-link" data-saas="revoke-invite" data-id="${esc(i.id)}">Revoke</button></div>`).join(''):'<p class="muted text-sm">No pending invitations. Make room for someone great.</p>'}</div></section>`:''}`)}<div class="role-grid mt">${[['Owner','Company settings, team, branding and billing.'],['Admin','CRM configuration, branding and agent/viewer invitations.'],['Agent','Contacts, conversation drafts, notes and sales pipeline.'],['Viewer','Read-only access to the workspace.']].map(([a,b])=>`<article class="card card-body"><h3>${a}</h3><p class="tiny muted mt">${b}</p></article>`).join('')}</div>`;
  }
  function billing() {
    return `${header('A little room to grow.', 'Understand your usage and choose the right next step.', '<button class="btn" data-saas="portal">Manage subscription ↗</button>')}${fetchView('billing','/billing', b=>`<section class="billing-summary card card-body"><div><p class="eyebrow">YOUR CURRENT PLAN</p><h2>${esc(b.limits.name)} <span class="badge ${b.status==='active'?'green':'amber'}">${esc(b.status==='trialing'&&b.trialEnd<Date.now()?'Trial ended':b.status)}</span></h2><p class="muted text-sm mt">${b.status==='trialing'?`Your trial ${b.trialEnd>Date.now()?'ends':'ended'} on ${new Date(b.trialEnd).toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric'})}.`: 'Your subscription status is synchronized from Stripe.'}</p></div><div class="billing-price">₹${b.limits.price.toLocaleString('en-IN')}<span>/ month after trial</span></div></section><div class="usage-grid mt">${Object.entries(b.usage).map(([key,value])=>`<article class="card card-body"><span class="tiny muted">${esc(key[0].toUpperCase()+key.slice(1))}</span><div class="usage-number">${value.toLocaleString()} <small>/ ${b.limits[key].toLocaleString()}</small></div><progress value="${value}" max="${b.limits[key]}" aria-label="${esc(key)} usage"></progress></article>`).join('')}</div>${!b.configured?alert('Stripe is not configured. Plan buttons will not charge you or change your subscription. Configure Stripe keys, recurring price IDs and a signed webhook on the server.'):alert('Checkout activates your plan only after a verified Stripe subscription event. Provider fees and applicable taxes are additional.')}<div class="pricing-grid mt">${planCards(true)}</div><p class="tiny muted mt">Limits count saved workspace records and reserved team seats. Existing records remain readable when a trial or subscription ends. Deleting a record frees its capacity.</p>`)}`;
  }
  function audit() { return `${header('A clear record of every step.', 'The latest 200 workspace events, recorded by the server.')}${fetchView('audit','/audit', rows=>`<section class="card"><div class="table-wrap"><table><thead><tr><th>Event</th><th>Actor</th><th>Details</th><th>When</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.action)}</strong></td><td>${esc(r.actor)}</td><td>${esc(r.details||'—')}</td><td>${new Date(r.at).toLocaleString('en-IN')}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No activity yet.</td></tr>'}</tbody></table></div></section>`)}`; }
  function security() { const a=S.account; return `${header('Confidence comes from clarity.', 'Your account and workspace access, in one place.')}<section class="card card-body"><div class="setting-row"><div><strong>Email verification</strong><p>${esc(a.user.email)} · ${a.user.verified?'Verified':'Not verified'}</p></div>${!a.user.verified?'<button class="btn small" data-saas="resend-verification">Send verification email</button>':'<span class="badge green">Verified</span>'}</div><div class="setting-row"><div><strong>Password recovery</strong><p>${a.emailConfigured?'Recovery links are delivered by your configured email service.':'Your administrator must configure SMTP to deliver recovery links.'}</p></div><a href="#forgot" class="btn small">Reset password</a></div><div class="setting-row"><div><strong>Session security</strong><p>HttpOnly cookies, CSRF verification and a 7-day session lifetime.</p></div><button class="btn small" data-saas="logout">Sign out</button></div><div class="setting-row"><div><strong>Workspace access</strong><p>Your role: ${esc(a.tenant.role)}. Membership is checked by the server on every request.</p></div><a href="#team" class="text-link">View team →</a></div><div class="setting-row"><div><strong>Export workspace data</strong><p>Download your company’s CRM data as JSON.</p></div><button class="btn small" data-action="export-data">Export data</button></div></section>${alert('This version provides password authentication and email verification. SSO, MFA, self-service account deletion and automated backups are not implemented. See the launch checklist in the project documentation.')}`; }
  function integrations() { return `${header('Connected with intention.', 'Know what is ready and what still needs a connection.')}<div class="grid grid-3">${[['WhatsApp Business','Not connected','The CRM stores drafts. Live sending, inbound webhooks, template approval, STOP handling and verified consent require a Meta integration.'],['Stripe Billing',S.account.billingConfigured?'Configured':'Not configured','Hosted checkout and the customer portal use server credentials. Subscription access changes through verified webhooks.'],['Email delivery',S.account.emailConfigured?'Configured':'Not configured','Verification, password recovery and team invitations use the server’s SMTP configuration.']].map(([name,status,body])=>`<article class="card card-body stack"><span class="badge ${status==='Configured'?'green':'gray'}">${status}</span><h2>${name}</h2><p class="text-sm muted">${body}</p></article>`).join('')}</div><section class="card card-body mt"><h2>Keep your credentials on the server.</h2><p class="muted text-sm mt">Connection secrets belong in the server environment. This workspace never asks your team to paste provider credentials into browser storage.</p><a href="#billing" class="btn mt">View billing →</a></section>`; }
  function onboarding() {
    const count = S.state.contacts.length;
    return `<section class="onboarding-card"><div><p class="eyebrow">MAKE YOURSELF AT HOME</p><h2>A few small steps.<br>A workspace that feels like yours.</h2><p>Your company starts with a clean slate.</p></div><div class="onboarding-steps"><a href="#branding"><span>${S.account.tenant.logo?'✓':'01'}</span><div><strong>Add your company identity</strong><small>Logo and brand color</small></div><b>↗</b></a><a href="#contacts"><span>${count?'✓':'02'}</span><div><strong>Bring your customers along</strong><small>Add a contact or import CSV</small></div><b>↗</b></a><a href="#team"><span>03</span><div><strong>Make room for your team</strong><small>Invite people and set roles</small></div><b>↗</b></a></div></section>`;
  }
  S.signupUrl = () => `subscribe.html?workspace=${encodeURIComponent(S.account?.tenant.slug || '')}`;
  S.nav = () => `<div class="nav-label saas-nav-label">ORGANIZATION</div><nav class="nav" aria-label="Organization">${[['branding','Brand identity','✳'],['team','Team members','♧'],['billing','Plans & billing','◈'],['audit','Audit history','◷'],['integrations','Integrations','↗'],['security','Account & security','◇']].filter(([id])=>id!=='audit'||['owner','admin'].includes(S.account.tenant.role)).map(([id,name,ico])=>`<a href="#${id}" class="nav-link ${S.route===id?'active':''}" ${S.route===id?'aria-current="page"':''}><span class="nav-saas-icon" aria-hidden="true">${ico}</span>${name}</a>`).join('')}${S.account.platformAdmin?`<div class="nav-label saas-nav-label platform-nav-label">PLATFORM</div><a href="#platform-admin" class="nav-link ${S.route==='platform-admin'?'active':''}" ${S.route==='platform-admin'?'aria-current="page"':''}><span class="nav-saas-icon" aria-hidden="true">◈</span>Admin console</a>`:''}</nav>`;
  S.banner = () => `<div class="workspace-status"><span><i class="dot"></i>${esc(S.account.tenant.name)} <span class="muted">/ ${esc(S.account.tenant.role)}</span></span><span id="save-status" role="status">${S.saving?'Saving…':'All changes saved'}</span></div>${S.account.tenant.suspended?alert('This workspace is suspended. You can view your data, but changes and WhatsApp sending are disabled. Contact the service operator.','error'):''}${S.notice?alert(esc(S.notice),'error'):''}`;
  S.customView = route => route==='integrations'&&S.whatsappIntegrations?S.whatsappIntegrations():route==='platform-admin'&&S.platformAdminView?S.platformAdminView():({ branding,team,billing,audit,security,integrations }[route]?.() || '');
  S.view = route => {
    S.route=route;
    const inviteToken = new URLSearchParams(location.hash.split('?')[1]).get('token');
    if (route==='accept-invite'&&inviteToken) { try { sessionStorage.setItem('techzolo_pending_invite',inviteToken); } catch {} }
    if (S.offline) return `<main id="main" class="setup-page">${S.brand(null)}<h1>Your SaaS server needs to be running.</h1><p>Open a terminal in this project, run <code>npm install</code>, then <code>npm start</code>.</p><p>Visit <a href="http://localhost:3000">http://localhost:3000</a> to create a company workspace.</p><button class="btn primary" data-saas="reload">Try again</button></main>`;
    if (route==='terms'||route==='privacy') return policy(route);
    if (route==='home' || (!location.hash&&!S.account)) return landing();
    if (publicRoutes.includes(route)) return auth(route);
    if (!S.account) return auth('login');
    return null;
  };
  S.dashboard = () => `${header(`A good day for ${esc(S.account.tenant.name)}.`, 'A clearer view of your customers, your conversations and what comes next.', '<a class="btn primary" href="#contacts">Add your first contact ↗</a>')}${onboarding()}<div class="grid grid-4 mt">${[['Contacts',S.state.contacts.length,'contacts'],['Conversation drafts',Object.keys(S.state.messages).length,'inbox'],['Campaign drafts',S.state.campaigns.length,'broadcasts'],['Open opportunities',S.state.deals.filter(d=>d.stage!=='Won').length,'pipelines']].map(([label,count,route])=>`<a href="#${route}" class="card card-body live-stat"><div class="row between"><span class="muted tiny">${label}</span><span>↗</span></div><strong>${count.toLocaleString()}</strong><span class="tiny muted">Your workspace records</span></a>`).join('')}</div><div class="grid grid-2 mt"><section class="card card-body"><p class="eyebrow">A PLACE FOR EVERY CONVERSATION</p><h2>Keep the context close.</h2><p class="muted text-sm mt">Find your customers, keep notes and prepare thoughtful replies from one shared inbox.</p><a class="btn mt" href="#inbox">Open shared inbox →</a></section><section class="card card-body"><p class="eyebrow">GROW AT YOUR OWN PACE</p><h2>Your next chapter starts here.</h2><p class="muted text-sm mt">Your ${esc(S.account.plans[S.account.tenant.plan].name)} ${S.account.tenant.status==='trialing'?'trial':'plan'} gives you room for ${S.account.plans[S.account.tenant.plan].seats} teammates. See usage and manage your subscription.</p><a href="#billing" class="btn mt">Explore your plan →</a></section></div>`;
  S.subscriber = () => {
    const b=S.publicBrand;
    if(!b)return `<main id="main" class="signup-wrap"><section class="signup-card">${S.brand(null)}<h1>Company signup page</h1>${alert(esc(S.notice||'Workspace not found.'))}<a href="index.html" class="btn">Visit Techzolo</a></section></main>`;
    return `<main id="main" class="signup-wrap"><section class="signup-card">${S.brand(b)}<p class="eyebrow">${esc(b.name)} · WHATSAPP OFFERS</p><h1>A little inspiration.<br>Offers you choose.</h1><p>Choose whether you’d like to hear from ${esc(b.name)} on WhatsApp.</p>${b.signupEnabled?`<form data-saas-form="subscriber" class="saas-form">${input('Your name','name','text','required maxlength="100" autocomplete="name"')}${input('WhatsApp number','phone','tel','required placeholder="+919000000000" autocomplete="tel"')}<label class="check-label"><input name="agreement" type="checkbox" required><span>I request WhatsApp offers from ${esc(b.name)}. I can reply STOP at any time. WhatsApp confirmation is required.</span></label>${b.privacy?`<a class="text-link tiny" href="${esc(b.privacy)}" target="_blank" rel="noopener">Company privacy policy ↗</a>`:''}<p class="form-error" role="alert"></p>${submit('Request to subscribe')}</form>`:alert('This company is not accepting subscriber requests right now.')}<p class="tiny muted mt">Submitting this form saves a pending request. It does not verify your WhatsApp number or start promotional messaging.</p></section></main>`;
  };
  S.requests = () => fetchView('requests','/subscriber-requests',rows=>`<section class="card mt"><div class="card-head mb"><h2>Pending website requests</h2><span class="badge amber">Confirmation required</span></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>WhatsApp number</th><th>Received</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.phone)}</td><td>${new Date(r.at).toLocaleString('en-IN')}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">No pending requests.</td></tr>'}</tbody></table></div></section>`);
  S.settings = () => {
    const s=S.state.settings;
    return `${header('Make this workspace yours.', 'Business details that help your team and customers feel at home.')}<div class="branding-layout"><section class="card"><form id="settings-form" class="card-body saas-form"><h2>Business profile</h2><div class="form-grid">${input('Company name','business','text','required maxlength="100"',s.business)}${input('Workspace owner display name','owner','text','required maxlength="100"',s.owner)}${input('Business email','email','email','required',s.email)}${input('WhatsApp business number','phone','tel','placeholder="+919000000000"',s.phone)}</div>${input('Published privacy policy','privacy','url','placeholder="https://your-company.com/privacy"',s.privacy)}<div class="field"><label for="saas-timezone">Workspace timezone</label><select id="saas-timezone" name="timezone">${['Asia/Kolkata','Asia/Dubai','Europe/London','America/New_York','UTC'].map(t=>`<option ${s.timezone===t?'selected':''}>${t}</option>`).join('')}</select></div><p class="tiny muted">Updating the owner display name does not transfer account ownership or change your sign-in details.</p><div class="form-footer">${submit('Save business details')}</div></form></section><aside class="stack"><section class="card card-body"><p class="eyebrow">LOOK FAMILIAR?</p><h2>Your brand belongs here.</h2><p class="tiny muted mt">Use your company logo and signature color throughout this workspace.</p><a class="btn mt" href="#branding">Edit brand identity →</a></section><section class="card card-body"><h2>The details that matter.</h2><div class="stack mt"><a class="text-link" href="#team">Team permissions →</a><a class="text-link" href="#billing">Plans & billing →</a><a class="text-link" href="#security">Account & security →</a><a class="text-link" href="#integrations">Connections →</a></div></section></aside></div>`;
  };
  S.subscribers = () => {
    const contacts=S.state.contacts, admins=['owner','admin'].includes(S.account.tenant.role);
    return `${header('Permission comes first.', 'Build a list of customers who choose to hear from you.', '<button class="btn primary" data-action="open-signup">Open company signup page ↗</button>')}<div class="grid grid-3 mb">${[['Verified WhatsApp subscribers',contacts.filter(c=>c.consent).length],['Not subscribed',contacts.filter(c=>!c.consent).length],['Company signup',S.state.settings.signupEnabled?'Enabled':'Disabled']].map(([label,value])=>`<article class="card card-body"><p class="tiny muted">${label}</p><h2 class="mt">${value}</h2></article>`).join('')}</div><section class="card card-body"><h2>A signup page with your identity.</h2><p class="muted text-sm mt">Your logo, company name and privacy policy follow your customers here.</p><div class="subscribe-link mt"><span class="grow">${esc(new URL(S.signupUrl(),location.href).href)}</span><button class="btn small" data-action="copy-signup">Copy link</button></div>${admins?`<button class="btn small mt" data-action="toggle-signup">${S.state.settings.signupEnabled?'Disable':'Enable'} signup requests</button>`:''}</section>${alert('Email marketing requires a separate confirmed opt-in. WhatsApp permission is confirmed through WhatsApp. Website signups and imported contacts remain pending until verified.')}<section class="card"><div class="card-head mb"><h2>WhatsApp contact preferences</h2></div><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Phone</th><th>Marketing permission</th><th>Action</th></tr></thead><tbody>${contacts.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.phone)}</td><td><span class="badge ${c.consent?'green':'gray'}">${c.consent?'Verified subscriber':'Not subscribed'}</span></td><td>${c.consent?`<button class="text-link" data-action="unsubscribe" data-id="${esc(c.id)}">Unsubscribe</button>`:'<span class="tiny muted">Confirmation required</span>'}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Add contacts to see their preferences.</td></tr>'}</tbody></table></div></section>${admins?S.requests():''}`;
  };
  S.reports = () => {
    const s=S.state, total=s.deals.reduce((n,d)=>n+d.value,0), won=s.deals.filter(d=>d.stage==='Won').reduce((n,d)=>n+d.value,0), money=v=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(v);
    return `${header('A clear view of your business.', 'Live counts from your workspace. No illustrative performance figures.', '<button class="btn" data-action="export-report">Export report</button>')}<div class="grid grid-4">${[['Contacts',s.contacts.length],['Opportunities',s.deals.length],['Pipeline value',money(total)],['Won value',money(won)]].map(([title,value])=>`<article class="card card-body live-stat"><span class="tiny muted">${title}</span><strong>${value}</strong></article>`).join('')}</div><section class="card card-body mt"><h2>Opportunity distribution</h2><div class="report-bars mt">${['New leads','Qualified','Proposal','Won'].map(stage=>{const count=s.deals.filter(d=>d.stage===stage).length;return `<div><div class="report-bar-head"><span>${stage}</span><strong>${count}</strong></div><progress value="${count}" max="${Math.max(s.deals.length,1)}" aria-label="${stage} opportunities"></progress></div>`;}).join('')}</div></section>${alert('Delivery, read rates and response-time analytics become available after a messaging provider is connected. Conversation entries in this version are drafts.')}`;
  };
  function policy(route) { return `<div class="marketing"><header class="marketing-nav"><a href="#home">${S.brand(null)}</a><a href="#signup" class="btn">Create workspace</a></header><main id="main" class="policy-page"><p class="eyebrow">TECHZOLO WORKSPACES</p><h1>${route==='terms'?'Workspace terms':'Privacy notice'}</h1>${alert('Development policy draft. The operator must publish its legal entity, support contact, retention schedule and applicable final terms before public launch.')} ${route==='terms'?'<h2>Using the workspace</h2><p>You are responsible for the company account, authorized teammates and lawful use of customer information. Do not upload content you lack permission to use or use the service for unsolicited messaging.</p><h2>Trials and billing</h2><p>The trial lasts 14 days. Paid subscriptions require a completed Stripe checkout and verified provider status. Configured prices and provider terms apply. WhatsApp and other third-party fees are separate.</p><h2>Service availability</h2><p>This development version offers CRM records, drafts, team permissions and workspace branding. WhatsApp sending and AI are not connected. No delivery, uptime or backup guarantee is provided by this development build.</p>':'<h2>What the app stores</h2><p>The server stores company details, account email, a salted password hash, team memberships, customer records, conversation drafts, logo images, audit events and pending subscriber requests in the application database.</p><h2>Sessions and storage</h2><p>An essential HttpOnly cookie identifies your signed-in session for up to seven days. Passwords, CRM records and session tokens are not stored in browser localStorage. An invitation token may temporarily use sessionStorage until accepted.</p><h2>External services</h2><p>If configured by the operator, email is delivered through its SMTP service and subscription payments are processed by Stripe. This app does not store payment card details. WhatsApp delivery is not connected.</p><h2>Data access and retention</h2><p>Authorized workspace users can export CRM data. Account deletion and retention requests currently require assistance from the deployment operator. The operator must publish its contact details, retention period and final privacy policy before launch.</p>'}<a href="#home" class="btn mt">← Back to home</a></main></div>`; }
  function modal(title, body) { const d=$('#dialog'); d.innerHTML=`<header class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-btn" data-action="close-dialog" aria-label="Close dialog">×</button></header><div class="dialog-body">${body}</div>`; if(!d.open)d.showModal(); }
  async function flush() { await S.pending; }
  async function sessionResult(account) { S.account=account; S.generation++; S.notice=''; S.logo=null; await S.loadWorkspace(); }
  document.addEventListener('click', async event => {
    if(event.target.closest('.skip-link')){event.preventDefault();const main=$('#main');if(main){main.tabIndex=-1;main.focus();main.scrollIntoView();}return;}
    const scroll=event.target.closest('[data-scroll]'); if(scroll){ event.preventDefault(); const target=scroll.dataset.scroll; if(location.hash!=='#home') { location.hash='home'; setTimeout(()=>$(`#${target}`)?.scrollIntoView({behavior:'smooth'}),50); } else $(`#${target}`)?.scrollIntoView({behavior:'smooth'}); return; }
    const b=event.target.closest('[data-saas]'); if(!b||!S.enabled)return;
    event.preventDefault(); event.stopImmediatePropagation();
    const action=b.dataset.saas;
    try {
      if(action==='reload'){ location.reload(); return; }
      if(action==='retry'){ delete S.cache[b.dataset.key]; S.refresh(); return; }
      if(action==='logout'){ await flush(); await S.api('/auth/logout','POST',{}); S.account=null; S.state=null; S.publicBrand=null; S.cache={}; S.syncBrand(); location.hash='login'; S.refresh(); return; }
      if(action==='workspace-menu'){ modal('Your workspaces',`<div class="stack">${S.account.workspaces.map(w=>`<button class="btn" data-saas="switch-workspace" data-id="${esc(w.id)}">${esc(w.name)} <span class="tiny muted">${esc(w.role)}</span></button>`).join('')}<hr><button class="btn primary" data-saas="new-workspace">Create another workspace ↗</button></div>`); return; }
      if(action==='new-workspace'){ S.logo=null; modal('Create a company workspace',`<form data-saas-form="workspace" class="saas-form">${companyFields()}<p class="form-error" role="alert"></p>${submit('Create workspace')}</form>`); return; }
      if(action==='switch-workspace'){ await flush(); await sessionResult(await S.api('/workspaces/switch','POST',{id:b.dataset.id})); $('#dialog').close(); location.hash='dashboard'; S.refresh(); return; }
      if(action==='invite'){ modal('Good work starts with good people.',`<form data-saas-form="invite" class="saas-form">${input('Teammate email','email','email','required')}<div class="field"><label for="invite-role">Access level</label><select id="invite-role" name="role">${(S.account.tenant.role==='owner'?['admin','agent','viewer']:['agent','viewer']).map(r=>`<option>${r}</option>`).join('')}</select></div><p class="tiny muted">Invitations expire in seven days and reserve a seat. The recipient must use this email address to join.</p><p class="form-error" role="alert"></p>${submit('Create invitation')}</form>`); return; }
      if(action==='remove-member'){ modal(`Remove ${b.dataset.name}?`,`<p>This person will lose access to this workspace immediately.</p><div class="form-footer"><button class="btn" data-action="close-dialog">Keep member</button><button class="btn danger" data-saas="confirm-remove-member" data-id="${esc(b.dataset.id)}">Remove member</button></div>`); return; }
      if(action==='confirm-remove-member'){ await S.api(`/team/${encodeURIComponent(b.dataset.id)}`,'DELETE',{}); $('#dialog').close(); delete S.cache.team; S.refresh(); S.notify('Team member removed.'); return; }
      if(action==='revoke-invite'){ await S.api(`/team/invites/${encodeURIComponent(b.dataset.id)}`,'DELETE',{}); delete S.cache.team; S.refresh(); S.notify('Invitation revoked.'); return; }
      if(action==='checkout'||action==='portal'){ await flush(); b.disabled=true; const result=await S.api(action==='checkout'?'/billing/checkout':'/billing/portal','POST',action==='checkout'?{plan:b.dataset.plan}:{}); const url=new URL(result.url); if(url.protocol!=='https:'||!['checkout.stripe.com','billing.stripe.com'].includes(url.hostname))throw new Error('Invalid billing destination.'); location.assign(url.href); return; }
      if(action==='resend-verification'){ const result=await S.api('/auth/resend-verification','POST',{}); S.notify(result.message); return; }
      if(action==='copy-invite'){ await navigator.clipboard.writeText($('#invite-link').value); S.notify('Invitation link copied.'); return; }
    } catch(e) { S.notify(e.message); } finally { b.disabled=false; }
  },true);
  // Protect the original CRM interactions as well as the administration screens.
  document.addEventListener('click',event=>{
    if(!S.enabled||!S.account)return;
    const el=event.target.closest('[data-action]'); if(!el)return;
    const a=el.dataset.action;
    if(['profile'].includes(a)){ event.preventDefault(); event.stopImmediatePropagation(); modal(S.account.user.name,`<p class="muted text-sm">${esc(S.account.user.email)} · ${esc(S.account.tenant.role)}</p><div class="stack mt"><a href="#security" class="btn" data-action="close-dialog">Account & security</a><button class="btn" data-saas="workspace-menu">Switch workspace</button><button class="btn" data-saas="logout">Sign out</button></div>`); return; }
    if(['reset','reset-confirm','campaign-toggle','campaign-step','forgot','integration-guide'].includes(a)){ event.preventDefault(); event.stopImmediatePropagation(); if(a==='integration-guide')location.hash='integrations'; else S.notify(a.startsWith('campaign')?'Connect WhatsApp before starting a campaign. Drafts never send messages.':'This action belongs to the legacy preview. Use Account & security for account actions.'); return; }
    if(a==='open-signup'||a==='copy-signup'){ event.preventDefault(); event.stopImmediatePropagation(); const link=new URL(S.signupUrl(),location.href).href; if(a==='open-signup')window.open(link,'_blank','noopener'); else navigator.clipboard.writeText(link).then(()=>S.notify('Company signup link copied.')).catch(()=>modal('Company signup link',`<input class="copy-link" value="${esc(link)}" readonly aria-label="Company signup link">`)); return; }
    const readActions=['menu','close-menu','close-dialog','chart-range','go-subscribers','select-chat','open-chat','campaign-detail','template-detail','choose-template','insert-template','test-flow','flow-choice','agent-preview','settings-tab','export-data','export-contacts','export-report','csv-example'];
    if(S.account.tenant.role==='viewer'&&!readActions.includes(a)){event.preventDefault();event.stopImmediatePropagation();S.notify('Your viewer role has read-only access.');}
    if(S.account.tenant.role==='agent'&&['new-campaign','new-template','add-automation','edit-automation','toggle-automation','toggle-signup','toggle-notifications'].includes(a)){event.preventDefault();event.stopImmediatePropagation();S.notify('Ask an administrator to change workspace configuration.');}
  },true);
  document.addEventListener('submit',async event=>{
    const form=event.target;if(!S.enabled||!form.matches('[data-saas-form]'))return;
    event.preventDefault();event.stopImmediatePropagation();
    if(form.dataset.busy)return; form.dataset.busy='true';
    const values=Object.fromEntries(new FormData(form)), kind=form.dataset.saasForm, button=form.querySelector('button[type="submit"]'), error=form.querySelector('.form-error');
    if(button)button.disabled=true;if(error)error.textContent='';
    const actionToken=new URLSearchParams(location.hash.split('?')[1]).get('token');
    try {
      if(['register','login'].includes(kind)){
        const body=kind==='register'?{...values,terms:values.terms==='on',logo:S.logo}:values;
        await sessionResult(await S.api(`/auth/${kind}`,'POST',body));
        let pending;try{pending=sessionStorage.getItem('techzolo_pending_invite');}catch{}
        location.hash=pending?`accept-invite?token=${pending}`:'dashboard';S.refresh();
      } else if(kind==='forgot'||kind==='reset'||kind==='verify'){
        const result=await S.api(`/auth/${kind}`,'POST',{...values,token:actionToken});
        if(kind==='forgot'){form.innerHTML=alert(esc(result.message));}else{location.hash='login';S.refresh();S.notify(result.message);}
      } else if(kind==='accept'){
        await flush(); await sessionResult(await S.api('/team/accept','POST',{token:actionToken}));try{sessionStorage.removeItem('techzolo_pending_invite');}catch{} location.hash='dashboard';S.refresh();S.notify('Welcome to your team workspace.');
      } else if(kind==='workspace'){
        await flush();await sessionResult(await S.api('/workspaces','POST',{...values,logo:S.logo}));$('#dialog').close();location.hash='dashboard';S.refresh();
      } else if(kind==='branding'){
        await flush();await sessionResult(await S.api('/branding','PUT',{color:values.color,logo:S.logo,removeLogo:values.removeLogo==='on'}));S.refresh();S.notify('Company branding saved.');
      } else if(kind==='invite'){
        const result=await S.api('/team/invite','POST',values);delete S.cache.team;S.refresh();modal('Your invitation is ready.',`<p>${result.delivered?'The invitation was sent by email.':'Email delivery is unavailable. Copy this link and share it with the invited teammate.'}</p><p class="tiny muted mt">Only ${esc(values.email)} can accept this invitation.</p><input id="invite-link" class="copy-link mt" value="${esc(result.link)}" readonly aria-label="Invitation link"><div class="form-footer"><button class="btn" data-saas="copy-invite">Copy invitation link</button><button class="btn primary" data-action="close-dialog">Done</button></div>`);
      } else if(kind==='subscriber'){
        const result=await S.api(`/public/${encodeURIComponent(S.publicBrand.slug)}/subscribe`,'POST',{...values,agreement:values.agreement==='on'});let confirm='';if(result.confirmUrl){const link=new URL(result.confirmUrl);if(link.protocol==='https:'&&link.hostname==='wa.me')confirm=`<a class="btn primary" href="${esc(link.href)}" target="_blank" rel="noopener">Confirm inside WhatsApp ↗</a>`;}form.innerHTML=alert(esc(result.message))+confirm;
      }
    }catch(e){if(error)error.textContent=e.message;else S.notify(e.message);}
    finally{delete form.dataset.busy;if(button)button.disabled=false;}
  },true);
  document.addEventListener('submit',event=>{if(!S.enabled||!S.account||event.target.matches('[data-saas-form]'))return;const form=event.target;if(form.id==='global-search')return;if(S.account.tenant.role==='viewer'||(S.account.tenant.role==='agent'&&['settings-form','agent-form'].includes(form.id))){event.preventDefault();event.stopImmediatePropagation();S.notify('Your role does not allow this change.');}},true);
  document.addEventListener('input',event=>{
    if(event.target.name==='company'&&event.target.form?.dataset.saasForm){const slug=event.target.form.elements.slug;if(!slug.dataset.edited)slug.value=event.target.value.toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,48);}
    if(event.target.name==='slug')event.target.dataset.edited='true';
    if(event.target.id==='saas-color'){const preview=$('#brand-live-preview');if(preview)preview.style.setProperty('--green',event.target.value);}
  });
  document.addEventListener('change',async event=>{
    const el=event.target;
    if(el.id==='company-logo'){
      const file=el.files?.[0];if(!file)return;
      if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024){S.notify('Choose a PNG, JPEG or WebP logo smaller than 2 MB.');el.value='';return;}
      try{S.logo=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});$('#logo-preview').innerHTML=`<img src="${esc(S.logo)}" alt="New company logo preview">`;}catch{S.logo=null;S.notify('Could not read this image.');}
    }
    if(el.dataset.member){try{await S.api(`/team/${encodeURIComponent(el.dataset.member)}`,'PATCH',{role:el.value});delete S.cache.team;S.refresh();S.notify('Team role updated.');}catch(e){delete S.cache.team;S.refresh();S.notify(e.message);}}
  });
  // Warn only while an actual write is outstanding; no customer records are cached locally.
  window.addEventListener('beforeunload',event=>{if(S.saving){event.preventDefault();event.returnValue='';}});
})();
